"use client"

import * as React from "react"

import {
  Drawer,
  DrawerClose,
  DrawerMenu,
  DrawerMenuGroup,
  DrawerMenuGroupLabel,
  DrawerMenuItem,
  DrawerMenuSeparator,
  DrawerPanel,
  DrawerPopup,
  DrawerTrigger,
} from "@/components/ui/drawer"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { useIsMobile } from "@/hooks/use-media-query"

type ResponsiveMenuContextValue = { isDesktop: boolean }

const ResponsiveMenuContext =
  React.createContext<ResponsiveMenuContextValue | null>(null)

function useResponsiveMenuContext() {
  const context = React.useContext(ResponsiveMenuContext)
  if (!context) {
    throw new Error(
      "ResponsiveMenu components must be used within <ResponsiveMenu>"
    )
  }
  return context
}

type ResponsiveMenuProps = {
  children: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

function ResponsiveMenu({
  children,
  open,
  defaultOpen,
  onOpenChange,
}: ResponsiveMenuProps) {
  const isDesktop = !useIsMobile()

  return (
    <ResponsiveMenuContext.Provider value={{ isDesktop }}>
      {isDesktop ? (
        <DropdownMenu
          open={open}
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
        >
          {children}
        </DropdownMenu>
      ) : (
        <Drawer
          open={open}
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
        >
          {children}
        </Drawer>
      )}
    </ResponsiveMenuContext.Provider>
  )
}

function ResponsiveMenuTrigger(
  props: React.ComponentProps<typeof DropdownMenuTrigger>
) {
  const { isDesktop } = useResponsiveMenuContext()
  return isDesktop ? (
    <DropdownMenuTrigger {...props} />
  ) : (
    <DrawerTrigger {...(props as React.ComponentProps<typeof DrawerTrigger>)} />
  )
}

type ResponsiveMenuContentProps = {
  children: React.ReactNode
  groupLabel?: string
  align?: React.ComponentProps<typeof DropdownMenuContent>["align"]
  side?: React.ComponentProps<typeof DropdownMenuContent>["side"]
  sideOffset?: number
  className?: string
}

function ResponsiveMenuContent({
  children,
  groupLabel,
  align = "end",
  side = "bottom",
  sideOffset = 6,
  className,
}: ResponsiveMenuContentProps) {
  const { isDesktop } = useResponsiveMenuContext()

  if (isDesktop) {
    return (
      <DropdownMenuContent
        align={align}
        side={side}
        sideOffset={sideOffset}
        className={className}
      >
        <DropdownMenuGroup>
          {groupLabel && (
            <DropdownMenuGroupLabel>{groupLabel}</DropdownMenuGroupLabel>
          )}
          {children}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    )
  }

  return (
    <DrawerPopup showBar>
      <DrawerPanel>
        <DrawerMenu>
          <DrawerMenuGroup>
            {groupLabel && (
              <DrawerMenuGroupLabel>{groupLabel}</DrawerMenuGroupLabel>
            )}
            {children}
          </DrawerMenuGroup>
        </DrawerMenu>
      </DrawerPanel>
    </DrawerPopup>
  )
}

type ResponsiveMenuItemProps = {
  children: React.ReactNode
  onClick?: () => void
  variant?: "default" | "destructive"
  disabled?: boolean
}

function ResponsiveMenuItem({
  children,
  onClick,
  variant = "default",
  disabled,
}: ResponsiveMenuItemProps) {
  const { isDesktop } = useResponsiveMenuContext()

  if (isDesktop) {
    return (
      <DropdownMenuItem variant={variant} disabled={disabled} onClick={onClick}>
        {children}
      </DropdownMenuItem>
    )
  }

  return (
    <DrawerClose
      render={<DrawerMenuItem variant={variant} disabled={disabled} />}
      onClick={onClick}
    >
      {children}
    </DrawerClose>
  )
}

function ResponsiveMenuSeparator() {
  const { isDesktop } = useResponsiveMenuContext()
  return isDesktop ? <DropdownMenuSeparator /> : <DrawerMenuSeparator />
}

export {
  ResponsiveMenu,
  ResponsiveMenuContent,
  ResponsiveMenuItem,
  ResponsiveMenuSeparator,
  ResponsiveMenuTrigger,
}

"use client"

import { useCallback, useSyncExternalStore } from "react"

const BREAKPOINTS = {
  "2xl": 1536,
  "3xl": 1600,
  "4xl": 2000,
  lg: 1024,
  md: 800,
  sm: 640,
  xl: 1280,
} as const

type Breakpoint = keyof typeof BREAKPOINTS
type BreakpointQuery =
  | Breakpoint
  | `max-${Breakpoint}`
  | `${Breakpoint}:max-${Breakpoint}`

function resolveMin(value: Breakpoint | number): string {
  const px = typeof value === "number" ? value : BREAKPOINTS[value]
  return `(min-width: ${px}px)`
}

function resolveMax(value: Breakpoint | number): string {
  const px = typeof value === "number" ? value : BREAKPOINTS[value]
  return `(max-width: ${px - 1}px)`
}

function parseQuery(
  query: BreakpointQuery | MediaQueryInput | (string & {})
): string {
  if (typeof query !== "string") {
    const parts: string[] = []
    if (query.min != null) parts.push(resolveMin(query.min))
    if (query.max != null) parts.push(resolveMax(query.max))
    if (query.pointer === "coarse") parts.push("(pointer: coarse)")
    if (query.pointer === "fine") parts.push("(pointer: fine)")
    if (parts.length === 0) return "(min-width: 0px)"
    return parts.join(" and ")
  }

  if (query.startsWith("(")) return query

  const parts: string[] = []
  for (const segment of query.split(":")) {
    if (segment.startsWith("max-")) {
      const bp = segment.slice(4)
      if (bp in BREAKPOINTS) parts.push(resolveMax(bp as Breakpoint))
    } else if (segment in BREAKPOINTS) {
      parts.push(resolveMin(segment as Breakpoint))
    }
  }

  return parts.length > 0 ? parts.join(" and ") : query
}

function getServerSnapshot(): boolean {
  return false
}

export type MediaQueryInput = {
  min?: Breakpoint | number
  max?: Breakpoint | number
  /** Touch-like input (finger). Use "fine" for mouse/trackpad. */
  pointer?: "coarse" | "fine"
}

/** Tracks a CSS media query with Tailwind-like breakpoint syntax. Returns `false` during SSR. */
export function useMediaQuery(
  query: BreakpointQuery | MediaQueryInput | (string & {})
): boolean {
  const mediaQuery = parseQuery(query)

  const subscribe = useCallback(
    (callback: () => void) => {
      if (typeof window === "undefined") return () => {}
      const mql = window.matchMedia(mediaQuery)
      mql.addEventListener("change", callback)
      return () => mql.removeEventListener("change", callback)
    },
    [mediaQuery]
  )

  const getSnapshot = useCallback(() => {
    if (typeof window === "undefined") return false
    return window.matchMedia(mediaQuery).matches
  }, [mediaQuery])

  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

export function useIsMobile(): boolean {
  return useMediaQuery("max-md")
}
